iso_week_index() {
  local d="$1"   # YYYYMMDD
  local dash="${d:0:4}-${d:4:2}-${d:6:2}"
  local out epoch dow mon
  out=$(date -u -d "$dash" '+%s %u')
  epoch=${out%% *}
  dow=${out##* }
  mon=$(( epoch - (dow - 1) * 86400 ))
  echo $(( mon / 604800 ))
}
for d in 20261007 20261005 20260930 20260929 20260922 20260915 20260908 20260101; do
  printf '%s -> %s\n' "$d" "$(iso_week_index "$d")"
done
echo "now=$(iso_week_index "$(date -u +%Y%m%d)")"

